import sys, os, re, json, math
from datetime import datetime, timedelta, timezone

CANON = ['temp', 'rh', 'pres', 'wspd', 'wdir', 'rain']
RANGE = {'temp': (-50, 60), 'rh': (0, 100), 'pres': (870, 1085),
         'wspd': (0, 60), 'wdir': (0, 360), 'rain': (0, 5000)}
CONV = {
    ('temp', 'degC'): lambda v: v, ('temp', 'degF'): lambda v: (v - 32) * 5 / 9,
    ('temp', 'K'): lambda v: v - 273.15,
    ('rh', 'pct'): lambda v: v, ('rh', 'frac'): lambda v: v * 100,
    ('pres', 'hPa'): lambda v: v, ('pres', 'kPa'): lambda v: v * 10,
    ('pres', 'inHg'): lambda v: v * 33.8638866667,
    ('pres', 'mmHg'): lambda v: v * 1.33322387415,
    ('wspd', 'ms'): lambda v: v, ('wspd', 'kmh'): lambda v: v / 3.6,
    ('wspd', 'kn'): lambda v: v * 1852 / 3600, ('wspd', 'mph'): lambda v: v * 0.44704,
    ('wdir', 'deg'): lambda v: v, ('rain', 'mm'): lambda v: v,
}
DIR = re.compile(r'^#\s*([a-z]+)\s*:(.*)$')
MISSING = re.compile(r'^-9999(\.0*)?$')
EPOCH = datetime(1970, 1, 1)


def secs(s):
    s = s.strip().replace('T', ' ')
    return int((datetime.strptime(s, '%Y-%m-%d %H:%M:%S') - EPOCH).total_seconds())


def tzoff(s):
    s = s.strip()
    if s == 'Z':
        return 0
    sign = -1 if s[0] == '-' else 1
    h, m = s[1:].split(':')
    return sign * (int(h) * 3600 + int(m) * 60)


def converter(q, unit):
    if (q, unit) in CONV:
        return CONV[(q, unit)]
    if q == 'rain' and unit.startswith('tips:'):
        S = float(unit[5:])
        return lambda v: v * S
    return lambda v: v


def parse_val(f):
    f = f.strip()
    if f == '' or f == '---' or f.lower() == 'nan' or MISSING.match(f):
        return None
    try:
        v = float(f)
    except ValueError:
        return None
    if math.isnan(v) or math.isinf(v):
        return None
    return v


def read_file(path):
    with open(path, 'rb') as fh:
        text = fh.read().decode('utf-8-sig')
    d = {'station': None, 'upload': 0, 'interval': None, 'tz': 0}
    cols = None
    units = {}
    convs = {}
    rows = []
    syncs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        if line[0] == '#':
            m = DIR.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k == 'station':
                d['station'] = v
            elif k == 'upload':
                d['upload'] = int(v)
            elif k == 'interval':
                d['interval'] = int(float(v))
            elif k == 'tz':
                d['tz'] = tzoff(v)
            elif k == 'columns':
                cols = [c.strip() for c in v.split(',')]
            elif k == 'units':
                for p in v.split():
                    if '=' in p:
                        q, u = p.split('=', 1)
                        units[q] = u
            elif k == 'sync':
                parts = {}
                for p in v.split():
                    if '=' in p:
                        a, b = p.split('=', 1)
                        parts[a] = b
                # logger time contains a space: re-parse
                mm = re.search(r'logger=(\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d)', v)
                rr = re.search(r'ref=(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ)', v)
                if mm and rr:
                    lt = secs(mm.group(1)) - d['tz']
                    syncs.append((lt, secs(rr.group(1).rstrip('Z')) - lt))
            continue
        fields = [x.strip() for x in line.split(',')]
        t = secs(fields[0] if cols is None or 'time' not in cols else fields[cols.index('time')]) - d['tz']
        vals = {}
        for c, f in zip(cols, fields):
            if c not in RANGE:
                continue
            v = parse_val(f)
            if v is not None:
                v = converter(c, units.get(c, {'temp': 'degC', 'rh': 'pct', 'pres': 'hPa', 'wspd': 'ms',
                                                'wdir': 'deg', 'rain': 'mm'}[c]))(v)
                lo, hi = RANGE[c]
                if not (lo <= v <= hi):
                    v = None
            if v is not None:
                vals[c] = v
        rows.append((t, vals))
    return d, rows, syncs


def offset_at(t, pts):
    if not pts:
        return 0
    if t <= pts[0][0]:
        return pts[0][1]
    if t >= pts[-1][0]:
        return pts[-1][1]
    import bisect
    i = bisect.bisect_left([p[0] for p in pts], t)
    if pts[i][0] == t:
        return pts[i][1]
    t1, o1 = pts[i - 1]
    t2, o2 = pts[i]
    return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)


def rnd(v):
    r = round(v + 0.0, 2)
    return 0.0 if r == 0 else r


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith('.log') or not os.path.isfile(p):
            continue
        d, rows, syncs = read_file(p)
        if d['station'] is None:
            continue
        s = stations.setdefault(d['station'], {'interval': d['interval'], 'rows': {}, 'sync': {}})
        if s['interval'] is None:
            s['interval'] = d['interval']
        up = d['upload']
        for t, vals in rows:
            old = s['rows'].get(t)
            if old is None or up >= old[0]:
                s['rows'][t] = (up, vals)
        for t, o in syncs:
            old = s['sync'].get(t)
            if old is None or up >= old[0]:
                s['sync'][t] = (up, o)
    result = []
    for sid in sorted(stations):
        s = stations[sid]
        if not s['rows']:
            continue
        interval = s['interval']
        pts = sorted((t, v[1]) for t, v in s['sync'].items())
        recs = []
        for t, (up, vals) in s['rows'].items():
            recs.append((t + offset_at(t, pts), vals))
        recs.sort(key=lambda r: r[0])
        hend = lambda c: -((-c) // 3600) * 3600
        byhour = {}
        for c, vals in recs:
            byhour.setdefault(hend(c), []).append((c, vals))
        h0, h1 = hend(recs[0][0]), hend(recs[-1][0])
        # rain increments
        inc = {}
        prev = None
        for c, vals in recs:
            if 'rain' in vals:
                r = vals['rain']
                if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                    inc[(c, id(vals))] = r - prev[1] if r >= prev[1] else r
                prev = (c, r)
        expected = 3600 / interval
        hours = []
        h = h0
        while h <= h1:
            entry = {'hour': (EPOCH + timedelta(seconds=h)).strftime('%Y-%m-%dT%H:00:00Z')}
            rs = byhour.get(h, [])
            for q in CANON:
                rd = [(c, v) for c, v in rs if q in v]
                n = len(rd)
                val = None
                if n and n * 4 >= expected * 3:
                    if q in ('temp', 'rh', 'pres', 'wspd'):
                        val = sum(v[q] for c, v in rd) / n
                    elif q == 'wdir':
                        sx = sy = 0.0
                        k = 0
                        for c, v in rd:
                            if v.get('wspd', 0) > 0 and 'wspd' in v:
                                a = math.radians(v['wdir'])
                                sx += math.sin(a)
                                sy += math.cos(a)
                                k += 1
                        if k:
                            val = math.degrees(math.atan2(sx, sy)) % 360
                    else:
                        val = sum(inc.get((c, id(v)), 0) for c, v in rd)
                elif q == 'rain' and False:
                    pass
                if val is not None:
                    val = rnd(val)
                    if val >= 360:
                        val = 0.0
                entry[q] = {'value': val, 'n': n}
            hours.append(entry)
            h += 3600
        result.append({'station': sid, 'interval_s': interval, 'hours': hours})
    with open(outfile, 'w') as f:
        json.dump({'stations': result}, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
